     1→'use client';
     2→
     3→import { FC, ReactNode, useMemo } from 'react';
     4→import {
     5→  useDoorHeight,
     6→  useDoorLayout,
     7→  useDoorLeftGlassWidth,
     8→  useDoorOpeningDirection,
     9→  useDoorRightGlassWidth,
    10→  useDoorUpperGlassHeight,
    11→  useDoorWidth,
    12→} from '../../store';
    13→
    14→// Convert mm to meters
    15→const mmToM = (mm: number) => mm / 1000;
    16→
    17→// Reference dimensions (what the original models were designed for)
    18→const REFERENCE_HEIGHT_MM = 2700;
    19→const REFERENCE_WIDTH_MM = 1250;
    20→
    21→interface HardwareGroupProps {
    22→  children: ReactNode;
    23→}
    24→
    25→/**
    26→ * Wrapper that transforms hardware components (handles, connectors, cylinder)
    27→ * from the original coordinate system to align with the parametric door.
    28→ *
    29→ * Original system:
    30→ * - Models designed for 2700mm height, 1250mm width door
    31→ * - Door bottom at Y=0 (in model space after 0.001 scale)
    32→ * - Door center at Y=1.35m
    33→ * - calculatePosition() shifts the group Y position based on door height
    34→ *
    35→ * Parametric system:
    36→ * - Door centered at origin (Y=0 at door center)
    37→ * - Door bottom at Y = -doorHeight/2 - topGlassOffset/2
    38→ * - Door top at Y = doorHeight/2 - topGlassOffset/2
    39→ *
    40→ * This component applies the transformation:
    41→ * - Shift Y to convert from "bottom at 0" to "center at 0" coordinate system
    42→ * - Offset for left/right glass panels (shifts door panel X)
    43→ * - Offset for top glass panel (shifts door panel Y)
    44→ */
    45→export const HardwareGroup: FC<HardwareGroupProps> = ({ children }) => {
    46→  const doorHeightMm = useDoorHeight();
    47→  const doorWidthMm = useDoorWidth();
    48→  const topGlassHeightMm = useDoorUpperGlassHeight();
    49→  const leftGlassWidthMm = useDoorLeftGlassWidth();
    50→  const rightGlassWidthMm = useDoorRightGlassWidth();
    51→  const layout = useDoorLayout();
    52→  const direction = useDoorOpeningDirection();
    53→
    54→  // Check which glass panels are active
    55→  const hasTopGlass = layout?.id?.includes('top') ?? false;
    56→  const hasLeftGlass = layout?.id?.includes('left') ?? false;
    57→  const hasRightGlass = layout?.id?.includes('right') ?? false;
    58→
    59→  // Convert to meters
    60→  const doorHeight = mmToM(doorHeightMm);
    61→  const doorWidth = mmToM(doorWidthMm);
    62→  const topGlassHeight = hasTopGlass ? mmToM(topGlassHeightMm) : 0;
    63→  const leftGlassWidth = hasLeftGlass ? mmToM(leftGlassWidthMm) : 0;
    64→  const rightGlassWidth = hasRightGlass ? mmToM(rightGlassWidthMm) : 0;
    65→
    66→  const isRightOpening = direction?.id === 'right';
    67→
    68→  // Calculate the transformation offset
    69→  const offset = useMemo(() => {
    70→    // The original models have door bottom at Y=0 (after 0.001 scale)
    71→    // and the reference door center is at Y = REFERENCE_HEIGHT/2 = 1.35m
    72→    //
    73→    // The calculatePosition() in original components shifts Y based on height:
    74→    // - At max height (2700mm): positionY = 0 (no shift)
    75→    // - At min height (1700mm): positionY = -0.4 to -0.5 (shifts down)
    76→    //
    77→    // In parametric space:
    78→    // - Door center is at Y = -topGlassHeight/2
    79→    // - We need to move the original coordinate system so its center aligns
    80→
    81→    // Base offset: move from "bottom at 0" to "center at 0" system
    82→    // Original center = referenceHeight / 2 = 1.35m
    83→    // Parametric center = 0 - topGlassOffset/2
    84→    // So we need to shift by: -(referenceHeight/2) - (topGlassHeight/2)
    85→    const referenceCenter = mmToM(REFERENCE_HEIGHT_MM) / 2;
    86→    const yOffset = -referenceCenter - topGlassHeight / 2;
    87→
    88→    // X offset for side glass panels
    89→    // Original models assume door is centered at X=0
    90→    // Parametric door panel center is at X = (leftGlassWidth - rightGlassWidth) / 2
    91→    const xOffset = (leftGlassWidth - rightGlassWidth) / 2;
    92→
    93→    // Additional X offset for door width difference from reference
    94→    // Original models positioned relative to 1250mm wide door
    95→    // We need to adjust handle/connector X positions for narrower doors
    96→    // This is already handled by calculatePosition() in the original components,
    97→    // but we may need minor adjustments
    98→
    99→    return {
   100→      x: xOffset,
   101→      y: yOffset,
   102→      z: 0,
   103→    };
   104→  }, [topGlassHeight, leftGlassWidth, rightGlassWidth]);
   105→
   106→  return (
   107→    <group position={[offset.x, offset.y, offset.z]}>
   108→      {children}
   109→    </group>
   110→  );
   111→};
   112→

