     1→'use client';
     2→
     3→import { useDoorSize } from '@modules/door-model/hooks/useDoorSize';
     4→import { DoorPanel, useDoorPanelBounds } from 'DoorPanel';
     5→import { FC, useMemo } from 'react';
     6→import {
     7→  useDoorGlassStyle,
     8→  useDoorLayout,
     9→  useDoorLeftGlassWidth,
    10→  useDoorRightGlassWidth,
    11→  useDoorSideGlassStyle,
    12→  useDoorUpperGlassHeight,
    13→  useFrameColor,
    14→  usePanelColor,
    15→} from '../../store';
    16→import { ParametricFrame } from './ParametricFrame';
    17→import { ParametricGlassPanel } from './ParametricGlassPanel';
    18→import { ParametricWall } from './ParametricWall';
    19→
    20→// Constants for door geometry (in meters)
    21→const FRAME_PROFILE_WIDTH = 0.066; // 66mm frame profile (sides and top)
    22→const FRAME_PROFILE_WIDTH_BOTTOM = 0.03; // 30mm frame profile (bottom)
    23→const PANEL_OFFSET_Z = 0.01; // Panel offset from center
    24→
    25→// Glass frame widths
    26→const GLASS_FRAME_STANDARD = 0.066; // 66mm standard glass frame
    27→const GLASS_FRAME_ADJACENT = 0.03; // 30mm where glass touches door
    28→
    29→// Convert mm to meters
    30→const mmToM = (mm: number) => mm / 1000;
    31→
    32→interface ParametricDoorProps {
    33→  showWall?: boolean;
    34→}
    35→
    36→/**
    37→ * Main parametric door component that integrates all parts:
    38→ * - Door panel with optional glass cutouts
    39→ * - Outer frame
    40→ * - Side glass panels (left, right, top)
    41→ * - Surrounding wall
    42→ *
    43→ * All dimensions are in meters (1 Three.js unit = 1 meter).
    44→ * Door width: 1.0m - 1.25m
    45→ * Door height: 2.2m - 2.9m
    46→ */
    47→
    48→export const ParametricDoor: FC<ParametricDoorProps> = ({
    49→  showWall = true,
    50→}) => {
    51→  const size = useDoorSize();
    52→
    53→  // Door dimensions derived from the 3D model's bounding box (already in meters)
    54→  const panelBounds = useDoorPanelBounds(size); // TODO: make size configurable
    55→  const doorWidth = panelBounds.width;
    56→  const doorHeight = panelBounds.height;
    57→
    58→  // Glass dimensions from store (stored in mm, convert to meters)
    59→  const topGlassHeightMm = useDoorUpperGlassHeight();
    60→  const leftGlassWidthMm = useDoorLeftGlassWidth();
    61→  const rightGlassWidthMm = useDoorRightGlassWidth();
    62→
    63→  const topGlassHeight = mmToM(topGlassHeightMm);
    64→  const leftGlassWidth = mmToM(leftGlassWidthMm);
    65→  const rightGlassWidth = mmToM(rightGlassWidthMm);
    66→
    67→  // Get layout and colors
    68→  const layout = useDoorLayout();
    69→  const frameColorItem = useFrameColor();
    70→  const panelColorItem = usePanelColor();
    71→  const glassStyle = useDoorGlassStyle();
    72→  const sideGlassStyle = useDoorSideGlassStyle();
    73→
    74→  // Parse colors (modelSrc contains hex color)
    75→  const frameColor = frameColorItem?.modelSrc || '#4a4a4a';
    76→  const panelColor = panelColorItem?.modelSrc || '#7a7a7a';
    77→  const glassColor = glassStyle?.modelSrc || '#87CEEB';
    78→  const sideGlassColor = sideGlassStyle?.modelSrc || '#87CEEB';
    79→
    80→  // Check if color items have materialId (for RAL materials from Blender)
    81→  const panelMaterialId = (panelColorItem as any)?.materialId;
    82→  const frameMaterialId = (frameColorItem as any)?.materialId;
    83→
    84→  // Determine which glass panels are visible based on layout
    85→  const hasTopGlass = layout?.id?.includes('top') ?? false;
    86→  const hasLeftGlass = layout?.id?.includes('left') ?? false;
    87→  const hasRightGlass = layout?.id?.includes('right') ?? false;
    88→
    89→  // Calculate actual glass dimensions (0 if not visible)
    90→  const actualTopGlassHeight = hasTopGlass ? topGlassHeight : 0;
    91→  const actualLeftGlassWidth = hasLeftGlass ? leftGlassWidth : 0;
    92→  const actualRightGlassWidth = hasRightGlass ? rightGlassWidth : 0;
    93→
    94→  // Calculate total opening dimensions for wall (includes all frames)
    95→  // Door frame adds 66mm on sides/top, 30mm on bottom
    96→  // Glass panels add their own frames (66mm on outer edges, 30mm where touching door)
    97→  const totalWidth = doorWidth + actualLeftGlassWidth + actualRightGlassWidth;
    98→  const totalHeight = doorHeight + actualTopGlassHeight;
    99→
   100→  // Wall opening must encompass entire assembly including all frames
   101→  // Width calculation: door + door frames + side glass panels (glass panel dimensions include frames)
   102→  const frameOuterWidth =
   103→    doorWidth +
   104→    actualLeftGlassWidth +
   105→    actualRightGlassWidth +
   106→    FRAME_PROFILE_WIDTH * 2; // door frame left & right (always present)
   107→
   108→  // Height calculation: door + frames
   109→  // Glass panel dimensions include their frames, so no extra height needed for side glass
   110→  const bottomOffset = FRAME_PROFILE_WIDTH_BOTTOM; // door frame bottom (30mm)
   111→
   112→  // Top offset: door frame top + optional top glass (glass panel height includes its frames)
   113→  let topOffset = FRAME_PROFILE_WIDTH; // door frame top (66mm, always present)
   114→  if (hasTopGlass) {
   115→    topOffset += actualTopGlassHeight; // top glass panel (frames already included)
   116→  }
   117→
   118→  const frameOuterHeight = doorHeight + bottomOffset + topOffset;
   119→
   120→  // Glass cutouts in the door panel (for future designs with integrated glass)
   121→  const glassCutouts = useMemo(() => {
   122→    // Currently no cutouts in the main panel
   123→    // This can be extended for door designs with built-in glass windows
   124→    return [{ x: 0, y: 0.5, width: 0.4, height: 0.6 }];
   125→  }, []);
   126→
   127→  // Calculate positions
   128→  // Door panel center X position (offset if side glass exists)
   129→  const doorPanelX = (actualLeftGlassWidth - actualRightGlassWidth) / 2;
   130→  // Door panel center Y position (offset if top glass exists)
   131→  const doorPanelY = -actualTopGlassHeight / 2;
   132→
   133→  // Side glass panels extend from door frame bottom to door frame top only
   134→  // Height: door + door frame top + door frame bottom (top glass sits on top of this)
   135→  const sideGlassHeight =
   136→    doorHeight + FRAME_PROFILE_WIDTH + FRAME_PROFILE_WIDTH_BOTTOM;
   137→  // Center Y: offset by difference between top and bottom frames
   138→  const sideGlassCenterY =
   139→    doorPanelY + (FRAME_PROFILE_WIDTH - FRAME_PROFILE_WIDTH_BOTTOM) / 2;
   140→
   141→  // Top glass width spans door + door frames + side glass panels
   142→  const topGlassWidth =
   143→    doorWidth +
   144→    FRAME_PROFILE_WIDTH * 2 + // door frame left & right (always present)
   145→    (hasLeftGlass ? actualLeftGlassWidth : 0) +
   146→    (hasRightGlass ? actualRightGlassWidth : 0);
   147→
   148→  // Top glass X position: adjust to center over the entire assembly including side glass
   149→  const topGlassCenterX =
   150→    doorPanelX + (actualRightGlassWidth - actualLeftGlassWidth) / 2;
   151→
   152→  return (
   153→    <group>
   154→      {/* Door panel (3D model), centered and positioned inside the frame */}
   155→      <DoorPanel
   156→        size={size}
   157→        position={[doorPanelX, doorPanelY, PANEL_OFFSET_Z]}
   158→      />
   159→
   160→      {/* Back panel (slightly offset) */}
   161→      {/* <ParametricDoorPanel
   162→        width={doorWidth}
   163→        height={doorHeight}
   164→        color={panelColor}
   165→        materialId={panelMaterialId}
   166→        glassCutouts={glassCutouts}
   167→        position={[doorPanelX, doorPanelY, -PANEL_OFFSET_Z]}
   168→        side="back"
   169→      /> */}
   170→
   171→      {/* Glass panels in door cutouts */}
   172→      {/* {glassCutouts.map((cutout, index) => (
   173→        <ParametricGlassPanel
   174→          key={index}
   175→          width={cutout.width}
   176→          height={cutout.height}
   177→          glassColor={glassColor}
   178→          frameColor={frameColor}
   179→          frameMaterialId={frameMaterialId}
   180→          includeFrame={false}
   181→          position={[doorPanelX + cutout.x, doorPanelY + cutout.y, 0]}
   182→        />
   183→      ))} */}
   184→
   185→      {/* Outer frame - only frames the door panel */}
   186→      <ParametricFrame
   187→        doorWidth={doorWidth}
   188→        doorHeight={doorHeight}
   189→        color={frameColor}
   190→        materialId={frameMaterialId}
   191→        position={[doorPanelX, doorPanelY, 0]}
   192→      />
   193→
   194→      {/* Left glass panel - extends from bottom to top, right edge (30mm) touches door frame (66mm) */}
   195→      {hasLeftGlass && (
   196→        <ParametricGlassPanel
   197→          width={actualLeftGlassWidth}
   198→          height={sideGlassHeight}
   199→          glassColor={sideGlassColor}
   200→          frameColor={frameColor}
   201→          frameMaterialId={frameMaterialId}
   202→          frameWidthTop={GLASS_FRAME_STANDARD}
   203→          frameWidthBottom={GLASS_FRAME_STANDARD}
   204→          frameWidthLeft={GLASS_FRAME_STANDARD}
   205→          frameWidthRight={GLASS_FRAME_ADJACENT}
   206→          position={[
   207→            doorPanelX -
   208→            doorWidth / 2 -
   209→            FRAME_PROFILE_WIDTH -
   210→            actualLeftGlassWidth / 2,
   211→            sideGlassCenterY,
   212→            0,
   213→          ]}
   214→        />
   215→      )}
   216→
   217→      {/* Right glass panel - extends from bottom to top, left edge (30mm) touches door frame (66mm) */}
   218→      {hasRightGlass && (
   219→        <ParametricGlassPanel
   220→          width={actualRightGlassWidth}
   221→          height={sideGlassHeight}
   222→          glassColor={sideGlassColor}
   223→          frameColor={frameColor}
   224→          frameMaterialId={frameMaterialId}
   225→          frameWidthTop={GLASS_FRAME_STANDARD}
   226→          frameWidthBottom={GLASS_FRAME_STANDARD}
   227→          frameWidthLeft={GLASS_FRAME_ADJACENT}
   228→          frameWidthRight={GLASS_FRAME_STANDARD}
   229→          position={[
   230→            doorPanelX +
   231→            doorWidth / 2 +
   232→            FRAME_PROFILE_WIDTH +
   233→            actualRightGlassWidth / 2,
   234→            sideGlassCenterY,
   235→            0,
   236→          ]}
   237→        />
   238→      )}
   239→
   240→      {/* Top glass panel - spans door + side glass widths, bottom edge (30mm) sits on top of door frame (66mm) */}
   241→      {hasTopGlass && (
   242→        <ParametricGlassPanel
   243→          width={topGlassWidth}
   244→          height={actualTopGlassHeight}
   245→          glassColor={glassColor}
   246→          frameColor={frameColor}
   247→          frameMaterialId={frameMaterialId}
   248→          frameWidthTop={GLASS_FRAME_STANDARD}
   249→          frameWidthBottom={GLASS_FRAME_ADJACENT}
   250→          frameWidthLeft={GLASS_FRAME_STANDARD}
   251→          frameWidthRight={GLASS_FRAME_STANDARD}
   252→          position={[
   253→            topGlassCenterX,
   254→            doorPanelY +
   255→            doorHeight / 2 +
   256→            FRAME_PROFILE_WIDTH +
   257→            actualTopGlassHeight / 2,
   258→            0,
   259→          ]}
   260→        />
   261→      )}
   262→
   263→      {/* Surrounding wall with door opening */}
   264→      {showWall && (
   265→        <ParametricWall
   266→          openingWidth={frameOuterWidth}
   267→          openingHeight={frameOuterHeight}
   268→          position={[0, 0, -0.05]}
   269→        />
   270→      )}
   271→    </group>
   272→  );
   273→};
   274→

