     1→'use client';
     2→
     3→import { useMemo } from 'react';
     4→import * as THREE from 'three';
     5→import { useDoorMaterial } from '../../hooks/useDoorMaterials';
     6→
     7→// Frame dimensions in meters
     8→const FRAME_PROFILE_WIDTH = 0.066; // 66mm frame profile width (sides and top)
     9→const FRAME_PROFILE_WIDTH_BOTTOM = 0.030; // 30mm frame profile width (bottom/threshold)
    10→const FRAME_PROFILE_DEPTH = 0.08; // 8cm frame profile depth
    11→
    12→interface ParametricFrameProps {
    13→  doorWidth: number; // inner door width in meters
    14→  doorHeight: number; // inner door height in meters
    15→  frameWidth?: number; // frame profile width
    16→  frameDepth?: number; // frame profile depth
    17→  color?: string;
    18→  // Optional: Use material ID to load RAL material from Blender
    19→  materialId?: string;
    20→  position?: [number, number, number];
    21→}
    22→
    23→/**
    24→ * Creates a door frame using box geometries.
    25→ * The frame only surrounds the door panel itself (not glass panels).
    26→ * Glass panels have their own separate frames.
    27→ * All dimensions in meters.
    28→ */
    29→export const ParametricFrame: React.FC<ParametricFrameProps> = ({
    30→  doorWidth,
    31→  doorHeight,
    32→  frameWidth = FRAME_PROFILE_WIDTH,
    33→  frameDepth = FRAME_PROFILE_DEPTH,
    34→  color = '#895129',
    35→  materialId,
    36→  position = [0, 0, 0],
    37→}) => {
    38→  // Load Blender material if materialId is provided
    39→  const blenderMaterial = useDoorMaterial(materialId);
    40→  // Frame only surrounds the door panel (doorWidth x doorHeight)
    41→  // Note: bottom frame uses narrower width (30mm) than sides/top (66mm)
    42→  const outerWidth = doorWidth + frameWidth * 2;
    43→
    44→  // Create frame pieces as box geometries (only around door panel)
    45→  const frameGeometries = useMemo(() => {
    46→    const pieces: {
    47→      geometry: THREE.BoxGeometry;
    48→      position: [number, number, number];
    49→    }[] = [];
    50→
    51→    // Bottom frame piece (threshold) - uses narrower width (30mm)
    52→    const bottomFrameWidth = FRAME_PROFILE_WIDTH_BOTTOM;
    53→    pieces.push({
    54→      geometry: new THREE.BoxGeometry(outerWidth, bottomFrameWidth, frameDepth),
    55→      position: [0, -doorHeight / 2 - bottomFrameWidth / 2, 0],
    56→    });
    57→
    58→    // Top frame piece - 66mm
    59→    pieces.push({
    60→      geometry: new THREE.BoxGeometry(outerWidth, frameWidth, frameDepth),
    61→      position: [0, doorHeight / 2 + frameWidth / 2, 0],
    62→    });
    63→
    64→    // Left frame piece - 66mm
    65→    pieces.push({
