    32→/**
    33→ * Creates a glass panel with optional surrounding frame.
    34→ * Used for side glass panels (left, right) and top glass panels.
    35→ * All dimensions in meters.
    36→ */
    37→export const ParametricGlassPanel: React.FC<ParametricGlassPanelProps> = ({
    38→  width,
    39→  height,
    40→  glassColor = '#87CEEB',
    41→  frameColor = '#895129',
    42→  frameMaterialId,
    43→  opacity = 0.4,
    44→  position = [0, 0, 0],
    45→  includeFrame = true,
    46→  frameWidthTop = GLASS_FRAME_WIDTH_STANDARD,
    47→  frameWidthBottom = GLASS_FRAME_WIDTH_STANDARD,
    48→  frameWidthLeft = GLASS_FRAME_WIDTH_STANDARD,
    49→  frameWidthRight = GLASS_FRAME_WIDTH_STANDARD,
