    53→  const glassGeometry = useMemo(() => {
    54→    return new THREE.BoxGeometry(width, height, GLASS_THICKNESS);
    55→  }, [width, height]);
    56→
    57→  const frameGeometries = useMemo(() => {
    58→    if (!includeFrame) return [];
    59→
    60→    const pieces: {
    61→      geometry: THREE.BoxGeometry;
    62→      position: [number, number, number];
    63→    }[] = [];
    64→
    65→    // Inner height for vertical pieces (accounting for top and bottom frame widths)
    66→    const innerHeight = height - frameWidthTop - frameWidthBottom;
    67→    // Y offset for vertical pieces (centered between top and bottom frames)
    68→    const verticalCenterY = (frameWidthBottom - frameWidthTop) / 2;
    69→
    70→    // Top frame piece
    71→    pieces.push({
    72→      geometry: new THREE.BoxGeometry(width, frameWidthTop, GLASS_FRAME_DEPTH),
    73→      position: [0, height / 2 - frameWidthTop / 2, 0],
    74→    });
    75→
    76→    // Bottom frame piece
    77→    pieces.push({
    78→      geometry: new THREE.BoxGeometry(width, frameWidthBottom, GLASS_FRAME_DEPTH),
    79→      position: [0, -height / 2 + frameWidthBottom / 2, 0],
    80→    });
    81→
    82→    // Left frame piece
    83→    pieces.push({
    84→      geometry: new THREE.BoxGeometry(frameWidthLeft, innerHeight, GLASS_FRAME_DEPTH),
    85→      position: [-width / 2 + frameWidthLeft / 2, verticalCenterY, 0],
    86→    });
    87→
    88→    // Right frame piece
    89→    pieces.push({
    90→      geometry: new THREE.BoxGeometry(frameWidthRight, innerHeight, GLASS_FRAME_DEPTH),
    91→      position: [width / 2 - frameWidthRight / 2, verticalCenterY, 0],
    92→    });
    93→
    94→    return pieces;
    95→  }, [width, height, includeFrame, frameWidthTop, frameWidthBottom, frameWidthLeft, frameWidthRight]);
    96→
    97→  return (
    98→    <group position={position}>
    99→      {/* Glass with realistic material */}
   100→      <mesh geometry={glassGeometry} castShadow receiveShadow>
   101→        <meshPhysicalMaterial
   102→          color={glassColor}
   103→          transparent
   104→          opacity={opacity}
   105→          transmission={0.9}
   106→          roughness={0.1}
   107→          metalness={0}
   108→          thickness={GLASS_THICKNESS}
   109→          ior={1.5}
   110→          side={THREE.DoubleSide}
   111→        />
   112→      </mesh>
   113→
   114→      {/* Frame around glass */}
   115→      {frameGeometries.map((piece, index) => (
   116→        <mesh
   117→          key={index}
   118→          geometry={piece.geometry}
   119→          position={piece.position}
   120→          castShadow
   121→          receiveShadow
   122→        >
   123→          {frameBlenderMaterial ? (
   124→            // Use Blender RAL material for frame
   125→            <primitive object={frameBlenderMaterial} attach="material" />
   126→          ) : (
   127→            // Fallback to simple color
   128→            <meshStandardMaterial color={frameColor} />
   129→          )}
   130→        </mesh>
   131→      ))}
   132→    </group>
   133→  );
   134→};
