     3→import { useMemo } from 'react';
     4→import * as THREE from 'three';
     5→
     6→// Fixed wall dimensions in meters — wall never changes size
     7→const WALL_WIDTH = 5.0; // 5m total wall width
     8→const WALL_HEIGHT = 3.5; // 3.5m total wall height
     9→const WALL_THICKNESS = 0.2; // 20cm wall thickness
    10→
    11→interface ParametricWallProps {
    12→  // Door opening dimensions (includes frame) — only the hole changes
    13→  openingWidth: number;
    14→  openingHeight: number;
    15→  wallColor?: string;
    16→  position?: [number, number, number];
    17→}
    18→
    19→/**
    20→ * Creates a wall with a door opening using Shape + ExtrudeGeometry.
    21→ * The wall has FIXED outer dimensions — only the door opening hole
    22→ * adjusts to match the current door configuration.
    23→ * All dimensions in meters.
    24→ */
    25→export const ParametricWall: React.FC<ParametricWallProps> = ({
    26→  openingWidth,
    27→  openingHeight,
    28→  wallColor = '#343534',
    29→  position = [0, 0, 0],
    30→}) => {
    31→  const geometry = useMemo(() => {
    32→    const halfWallW = WALL_WIDTH / 2;
    33→    const halfOpenW = openingWidth / 2;
    34→    const halfOpenH = openingHeight / 2;
    35→
    36→    // Wall bottom aligns with the bottom of the door opening
    37→    const wallBottom = -halfOpenH;
    38→    const wallTop = wallBottom + WALL_HEIGHT;
    39→    const wallLeft = -halfWallW;
    40→    const wallRight = halfWallW;
    41→
    42→    // Create wall shape with door opening as a hole
    43→    const shape = new THREE.Shape();
    44→
    45→    // Outer wall rectangle (fixed size)
    46→    shape.moveTo(wallLeft, wallBottom);
    47→    shape.lineTo(wallRight, wallBottom);
    48→    shape.lineTo(wallRight, wallTop);
    49→    shape.lineTo(wallLeft, wallTop);
    50→    shape.closePath();
    51→
    52→    // Door opening hole (dynamic)
    53→    const hole = new THREE.Path();
    54→    hole.moveTo(-halfOpenW, -halfOpenH);
    55→    hole.lineTo(-halfOpenW, halfOpenH);
    56→    hole.lineTo(halfOpenW, halfOpenH);
    57→    hole.lineTo(halfOpenW, -halfOpenH);
    58→    hole.closePath();
    59→
    60→    shape.holes.push(hole);
    61→
    62→    const extrudeSettings: THREE.ExtrudeGeometryOptions = {
    63→      depth: WALL_THICKNESS,
    64→      bevelEnabled: false,
    65→    };
    66→
    67→    const geom = new THREE.ExtrudeGeometry(shape, extrudeSettings);
    68→    geom.translate(0, 0, -WALL_THICKNESS / 2);
    69→
    70→    return geom;
    71→  }, [openingWidth, openingHeight]);
    72→
    73→  return (
    74→    <mesh geometry={geometry} position={position} castShadow receiveShadow>
    75→      <meshStandardMaterial color={wallColor} side={THREE.DoubleSide} />
    76→    </mesh>
    77→  );
    78→};
