### 4. ParametricWall Component

```tsx
'use client';

import { useMemo } from 'react';
import * as THREE from 'three';

// Fixed wall dimensions in meters — wall never changes size
const WALL_WIDTH = 5.0; // 5m total wall width
const WALL_HEIGHT = 3.5; // 3.5m total wall height
const WALL_THICKNESS = 0.2; // 20cm wall thickness

interface ParametricWallProps {
  // Door opening dimensions (includes frame) — only the hole changes
  openingWidth: number;
  openingHeight: number;
  wallColor?: string;
  position?: [number, number, number];
}

/**
 * Creates a wall with a door opening using Shape + ExtrudeGeometry.
 * The wall has FIXED outer dimensions — only the door opening hole
 * adjusts to match the current door configuration.
 * All dimensions in meters.
 */
export const ParametricWall: React.FC<ParametricWallProps> = ({
  openingWidth,
  openingHeight,
  wallColor = '#343534',
  position = [0, 0, 0],
}) => {
  const geometry = useMemo(() => {
    const halfWallW = WALL_WIDTH / 2;
    const halfOpenW = openingWidth / 2;
    const halfOpenH = openingHeight / 2;

    // Wall bottom aligns with the bottom of the door opening
    const wallBottom = -halfOpenH;
    const wallTop = wallBottom + WALL_HEIGHT;
    const wallLeft = -halfWallW;
    const wallRight = halfWallW;

    // Create wall shape with door opening as a hole
    const shape = new THREE.Shape();

    // Outer wall rectangle (fixed size)
    shape.moveTo(wallLeft, wallBottom);
    shape.lineTo(wallRight, wallBottom);
    shape.lineTo(wallRight, wallTop);
    shape.lineTo(wallLeft, wallTop);
    shape.closePath();

    // Door opening hole (dynamic)
    const hole = new THREE.Path();
    hole.moveTo(-halfOpenW, -halfOpenH);
    hole.lineTo(-halfOpenW, halfOpenH);
    hole.lineTo(halfOpenW, halfOpenH);
    hole.lineTo(halfOpenW, -halfOpenH);
    hole.closePath();

    shape.holes.push(hole);

    const extrudeSettings: THREE.ExtrudeGeometryOptions = {
      depth: WALL_THICKNESS,
      bevelEnabled: false,
    };

    const geom = new THREE.ExtrudeGeometry(shape, extrudeSettings);
    geom.translate(0, 0, -WALL_THICKNESS / 2);

    return geom;
  }, [openingWidth, openingHeight]);

  return (
    <mesh geometry={geometry} position={position} castShadow receiveShadow>
      <meshStandardMaterial color={wallColor} side={THREE.DoubleSide} />
    </mesh>
  );
};
```

