'use client';

import { useMemo } from 'react';
import * as THREE from 'three';
import { useDoorMaterial } from '../../hooks/useDoorMaterials';

// Glass panel thickness in meters
const GLASS_THICKNESS = 0.01; // 1cm thick glass

// Glass frame (mullion) dimensions
const GLASS_FRAME_WIDTH_STANDARD = 0.066; // 66mm frame around glass (standard)
const GLASS_FRAME_WIDTH_ADJACENT = 0.030; // 30mm frame where touching door panel
const GLASS_FRAME_DEPTH = 0.08; // 8cm depth (matches door frame depth)

interface ParametricGlassPanelProps {
  width: number; // in meters
  height: number; // in meters
  glassColor?: string;
  frameColor?: string;
  // Optional: Use material ID for frame material from Blender
  frameMaterialId?: string;
  opacity?: number;
  position?: [number, number, number];
  includeFrame?: boolean;
  // Individual frame widths (for asymmetric frames where glass touches door)
  frameWidthTop?: number;
  frameWidthBottom?: number;
  frameWidthLeft?: number;
  frameWidthRight?: number;
}

/**
 * Creates a glass panel with optional surrounding frame.
 * Used for side glass panels (left, right) and top glass panels.
 * All dimensions in meters.
 */
export const ParametricGlassPanel: React.FC<ParametricGlassPanelProps> = ({
  width,
  height,
  glassColor = '#87CEEB',
  frameColor = '#895129',
  frameMaterialId,
  opacity = 0.4,
  position = [0, 0, 0],
  includeFrame = true,
  frameWidthTop = GLASS_FRAME_WIDTH_STANDARD,
  frameWidthBottom = GLASS_FRAME_WIDTH_STANDARD,
  frameWidthLeft = GLASS_FRAME_WIDTH_STANDARD,
  frameWidthRight = GLASS_FRAME_WIDTH_STANDARD,
}) => {
  // Load Blender material for frame if materialId is provided
  const frameBlenderMaterial = useDoorMaterial(frameMaterialId);
  const glassGeometry = useMemo(() => {
    return new THREE.BoxGeometry(width, height, GLASS_THICKNESS);
  }, [width, height]);

  const frameGeometries = useMemo(() => {
    if (!includeFrame) return [];

    const pieces: {
      geometry: THREE.BoxGeometry;
      position: [number, number, number];
    }[] = [];

    // Inner height for vertical pieces (accounting for top and bottom frame widths)
    const innerHeight = height - frameWidthTop - frameWidthBottom;
    // Y offset for vertical pieces (centered between top and bottom frames)
    const verticalCenterY = (frameWidthBottom - frameWidthTop) / 2;

    // Top frame piece
    pieces.push({
      geometry: new THREE.BoxGeometry(width, frameWidthTop, GLASS_FRAME_DEPTH),
      position: [0, height / 2 - frameWidthTop / 2, 0],
    });

    // Bottom frame piece
    pieces.push({
      geometry: new THREE.BoxGeometry(width, frameWidthBottom, GLASS_FRAME_DEPTH),
      position: [0, -height / 2 + frameWidthBottom / 2, 0],
    });

    // Left frame piece
    pieces.push({
      geometry: new THREE.BoxGeometry(frameWidthLeft, innerHeight, GLASS_FRAME_DEPTH),
      position: [-width / 2 + frameWidthLeft / 2, verticalCenterY, 0],
    });

    // Right frame piece
    pieces.push({
      geometry: new THREE.BoxGeometry(frameWidthRight, innerHeight, GLASS_FRAME_DEPTH),
      position: [width / 2 - frameWidthRight / 2, verticalCenterY, 0],
    });

    return pieces;
  }, [width, height, includeFrame, frameWidthTop, frameWidthBottom, frameWidthLeft, frameWidthRight]);

  return (
    <group position={position}>
      {/* Glass with realistic material */}
      <mesh geometry={glassGeometry} castShadow receiveShadow>
        <meshPhysicalMaterial
          color={glassColor}
          transparent
          opacity={opacity}
          transmission={0.9}
          roughness={0.1}
          metalness={0}
          thickness={GLASS_THICKNESS}
          ior={1.5}
          side={THREE.DoubleSide}
        />
      </mesh>

      {/* Frame around glass */}
      {frameGeometries.map((piece, index) => (
        <mesh
          key={index}
          geometry={piece.geometry}
          position={piece.position}
          castShadow
          receiveShadow
        >
          {frameBlenderMaterial ? (
            // Use Blender RAL material for frame
            <primitive object={frameBlenderMaterial} attach="material" />
          ) : (
            // Fallback to simple color
            <meshStandardMaterial color={frameColor} />
          )}
        </mesh>
      ))}
    </group>
  );
};
