### 7. ParametricDoorPanel Component

```tsx
'use client';

import { useMemo } from 'react';
import * as THREE from 'three';
import { useDoorMaterial } from '../../hooks/useDoorMaterials';

// Door panel thickness in meters
const PANEL_THICKNESS = 0.05;

interface GlassCutout {
  x: number; // center X position
  y: number; // center Y position
  width: number;
  height: number;
}

interface ParametricDoorPanelProps {
  width: number; // in meters (1.0 - 1.25)
  height: number; // in meters (2.2 - 2.9)
  thickness?: number;
  color?: string;
  // Optional: Use material ID to load RAL material from Blender
  materialId?: string;
  glassCutouts?: GlassCutout[];
  position?: [number, number, number];
  side?: 'front' | 'back';
}

/**
 * Creates a door panel geometry using THREE.Shape with holes for glass cutouts.
 * This approach avoids the stretching problem of scaling pre-made meshes.
 * Dimensions are in meters (1 Three.js unit = 1 meter).
 */
export const ParametricDoorPanel: React.FC<ParametricDoorPanelProps> = ({
  width,
  height,
  thickness = PANEL_THICKNESS,
  color = '#895129',
  materialId,
  glassCutouts = [],
  position = [0, 0, 0],
  side = 'front',
}) => {
  // Load Blender material if materialId is provided
  const blenderMaterial = useDoorMaterial(materialId);

  const geometry = useMemo(() => {
    // Create the main panel shape (centered at origin)
    const shape = new THREE.Shape();
    const halfW = width / 2;
    const halfH = height / 2;

    // Draw outer rectangle (counter-clockwise for front face)
    shape.moveTo(-halfW, -halfH);
    shape.lineTo(halfW, -halfH);
    shape.lineTo(halfW, halfH);
    shape.lineTo(-halfW, halfH);
    shape.closePath();

    // Add holes for each glass cutout
    glassCutouts.forEach((cutout) => {
      const hole = new THREE.Path();
      const cx = cutout.x;
      const cy = cutout.y;
      const hw = cutout.width / 2;
      const hh = cutout.height / 2;

      // Draw hole (clockwise to create a hole)
      hole.moveTo(cx - hw, cy - hh);
      hole.lineTo(cx - hw, cy + hh);
      hole.lineTo(cx + hw, cy + hh);
      hole.lineTo(cx + hw, cy - hh);
      hole.closePath();

      shape.holes.push(hole);
    });

    // Extrude to give thickness
    const extrudeSettings: THREE.ExtrudeGeometryOptions = {
      depth: thickness,
      bevelEnabled: false,
    };

    const geom = new THREE.ExtrudeGeometry(shape, extrudeSettings);

    // Center the geometry on Z axis
    geom.translate(0, 0, -thickness / 2);

    return geom;
  }, [width, height, thickness, glassCutouts]);

  return (
    <mesh
      geometry={geometry}
      position={position}
      rotation={side === 'back' ? [0, Math.PI, 0] : [0, 0, 0]}
      castShadow
      receiveShadow
    >
      {blenderMaterial ? (
        <primitive object={blenderMaterial} attach="material" />
      ) : (
        <meshStandardMaterial color={color} side={THREE.DoubleSide} />
      )}
    </mesh>
  );
};
