### 8. HardwareGroup Component (Transformation Wrapper)

```tsx
'use client';

import { FC, ReactNode, useMemo } from 'react';
import {
  useDoorHeight,
  useDoorLayout,
  useDoorLeftGlassWidth,
  useDoorOpeningDirection,
  useDoorRightGlassWidth,
  useDoorUpperGlassHeight,
  useDoorWidth,
} from '../../store';

// Convert mm to meters
const mmToM = (mm: number) => mm / 1000;

// Reference dimensions (what the original models were designed for)
const REFERENCE_HEIGHT_MM = 2700;
const REFERENCE_WIDTH_MM = 1250;

interface HardwareGroupProps {
  children: ReactNode;
}

/**
 * Wrapper that transforms hardware components (handles, connectors, cylinder)
 * from the original coordinate system to align with the parametric door.
 *
 * Original system:
 * - Models designed for 2700mm height, 1250mm width door
 * - Door bottom at Y=0 (in model space after 0.001 scale)
 * - Door center at Y=1.35m
 * - calculatePosition() shifts the group Y position based on door height
 *
 * Parametric system:
 * - Door centered at origin (Y=0 at door center)
 * - Door bottom at Y = -doorHeight/2 - topGlassOffset/2
 * - Door top at Y = doorHeight/2 - topGlassOffset/2
 *
 * This component applies the transformation:
 * - Shift Y to convert from "bottom at 0" to "center at 0" coordinate system
 * - Offset for left/right glass panels (shifts door panel X)
 * - Offset for top glass panel (shifts door panel Y)
 */
export const HardwareGroup: FC<HardwareGroupProps> = ({ children }) => {
  const doorHeightMm = useDoorHeight();
  const doorWidthMm = useDoorWidth();
  const topGlassHeightMm = useDoorUpperGlassHeight();
  const leftGlassWidthMm = useDoorLeftGlassWidth();
  const rightGlassWidthMm = useDoorRightGlassWidth();
  const layout = useDoorLayout();
  const direction = useDoorOpeningDirection();

  // Check which glass panels are active
  const hasTopGlass = layout?.id?.includes('top') ?? false;
  const hasLeftGlass = layout?.id?.includes('left') ?? false;
  const hasRightGlass = layout?.id?.includes('right') ?? false;

  // Convert to meters
  const doorHeight = mmToM(doorHeightMm);
  const doorWidth = mmToM(doorWidthMm);
  const topGlassHeight = hasTopGlass ? mmToM(topGlassHeightMm) : 0;
  const leftGlassWidth = hasLeftGlass ? mmToM(leftGlassWidthMm) : 0;
  const rightGlassWidth = hasRightGlass ? mmToM(rightGlassWidthMm) : 0;

  const isRightOpening = direction?.id === 'right';

  // Calculate the transformation offset
  const offset = useMemo(() => {
    // The original models have door bottom at Y=0 (after 0.001 scale)
    // and the reference door center is at Y = REFERENCE_HEIGHT/2 = 1.35m
    //
    // The calculatePosition() in original components shifts Y based on height:
    // - At max height (2700mm): positionY = 0 (no shift)
    // - At min height (1700mm): positionY = -0.4 to -0.5 (shifts down)
    //
    // In parametric space:
    // - Door center is at Y = -topGlassHeight/2
    // - We need to move the original coordinate system so its center aligns

    // Base offset: move from "bottom at 0" to "center at 0" system
    // Original center = referenceHeight / 2 = 1.35m
    // Parametric center = 0 - topGlassOffset/2
    // So we need to shift by: -(referenceHeight/2) - (topGlassHeight/2)
    const referenceCenter = mmToM(REFERENCE_HEIGHT_MM) / 2;
    const yOffset = -referenceCenter - topGlassHeight / 2;

    // X offset for side glass panels
    // Original models assume door is centered at X=0
    // Parametric door panel center is at X = (leftGlassWidth - rightGlassWidth) / 2
    const xOffset = (leftGlassWidth - rightGlassWidth) / 2;

    // Additional X offset for door width difference from reference
    // Original models positioned relative to 1250mm wide door
    // We need to adjust handle/connector X positions for narrower doors
    // This is already handled by calculatePosition() in the original components,
    // but we may need minor adjustments

    return {
      x: xOffset,
      y: yOffset,
      z: 0,
    };
  }, [topGlassHeight, leftGlassWidth, rightGlassWidth]);

  return (
    <group position={[offset.x, offset.y, offset.z]}>
      {children}
    </group>
  );
};
